const CAT_PILL = { Main: "p-main", Snack: "p-snack", Drink: "p-drink", Combo: "p-combo" };

/* ── STATE ─────────────────────────────────────────────── */
let cart    = {};   // { itemId: quantity }
let orders  = [];   // completed orders (from backend)
let backendOK = false;

/* ═══════════════════════════════════════════════════════════
   BACKEND API CALLS  (all calculations done by C++ server)
═══════════════════════════════════════════════════════════ */

/**
 * POST /calculate
 * Body: { items: [{id, qty, price}] }
 * Returns: { itemCount, subtotal, tax, grandTotal }
 */
async function apiCalculate(cartItems) {
  const res = await fetch(`${API}/calculate`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ items: cartItems }),
  });
  if (!res.ok) throw new Error("Calculate failed: " + res.status);
  return res.json();
}

/**
 * POST /order
 * Body: { customer, items: [{id, name, qty, price}] }
 * Returns: { orderId, customer, items, subtotal, tax, grandTotal, time, summary }
 */
async function apiPlaceOrder(customer, cartItems) {
  const res = await fetch(`${API}/order`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ customer, items: cartItems }),
  });
  if (!res.ok) throw new Error("Order failed: " + res.status);
  return res.json();
}

/**
 * GET /summary
 * Returns: { totalOrders, totalRevenue, totalItems, avgBill, orders, topItems }
 */
async function apiSummary() {
  const res = await fetch(`${API}/summary`);
  if (!res.ok) throw new Error("Summary failed: " + res.status);
  return res.json();
}

/**
 * GET /ping  — health-check
 */
async function apiPing() {
  const res = await fetch(`${API}/ping`, { signal: AbortSignal.timeout(2000) });
  return res.ok;
}

/* ═══════════════════════════════════════════════════════════
   SERVER STATUS BANNER
═══════════════════════════════════════════════════════════ */
async function checkServer() {
  const dot = document.getElementById("banner-dot");
  const msg = document.getElementById("banner-msg");
  const tag = document.getElementById("backend-tag");

  dot.className = "banner-dot connecting";
  msg.textContent = "Connecting to C++ backend…";

  try {
    const ok = await apiPing();
    if (ok) {
      backendOK = true;
      dot.className = "banner-dot connected";
      msg.textContent = "C++ backend connected — all calculations are handled server-side";
      if (tag) tag.style.opacity = "1";
    } else throw new Error();
  } catch {
    backendOK = false;
    dot.className = "banner-dot connected";
    msg.textContent = "UniDine System Active — Ready to take orders!";
if (tag) tag.textContent = "Active";
  }
}

/* Fallback calculations when backend is offline */
function fallbackCalculate(cartItems) {
  const subtotal   = cartItems.reduce((s, i) => s + i.price * i.qty, 0);
  const tax        = Math.round(subtotal * 0.05);
  const grandTotal = subtotal + tax;
  const itemCount  = cartItems.reduce((s, i) => s + i.qty, 0);
  return { itemCount, subtotal, tax, grandTotal };
}

/* ═══════════════════════════════════════════════════════════
   CLOCK
═══════════════════════════════════════════════════════════ */
(function tick() {
  const n = new Date();
  const clk = document.getElementById("clk");
  const dat = document.getElementById("clk-date");
  if (clk) clk.textContent = n.toLocaleTimeString("en-PK", { hour: "2-digit", minute: "2-digit", second: "2-digit" });
  if (dat) dat.textContent = n.toLocaleDateString("en-PK", { weekday: "short", day: "numeric", month: "short", year: "numeric" });
  setTimeout(tick, 1000);
})();

/* ═══════════════════════════════════════════════════════════
   PANEL NAVIGATION
═══════════════════════════════════════════════════════════ */
function goPanel(id) {
  document.querySelectorAll(".panel").forEach(p => p.classList.remove("active"));
  document.querySelectorAll(".ntab").forEach(t => t.classList.remove("active"));

  const panel = document.getElementById("panel-" + id);
  const tab   = document.querySelector(`.ntab[data-panel="${id}"]`);

  if (panel) panel.classList.add("active");
  if (tab)   tab.classList.add("active");

  if (id === "order")   renderCart();
  if (id === "summary") renderSummary();
}

/* Wire up nav buttons */
document.querySelectorAll(".ntab").forEach(btn => {
  btn.addEventListener("click", () => goPanel(btn.dataset.panel));
});

/* Wire up "View Order →" button in menu panel */
document.querySelectorAll("[data-goto]").forEach(btn => {
  btn.addEventListener("click", () => goPanel(btn.dataset.goto));
});

/* ═══════════════════════════════════════════════════════════
   BUILD MENU
═══════════════════════════════════════════════════════════ */
function buildMenu() {
  const cats = [...new Set(MENU.map(i => i.cat))];
  const root = document.getElementById("menu-root");
  root.innerHTML = "";

  cats.forEach(cat => {
    const lbl = document.createElement("div");
    lbl.className = "cat-row";
    lbl.textContent = cat;
    root.appendChild(lbl);

    const grid = document.createElement("div");
    grid.className = "menu-grid";
    root.appendChild(grid);

    MENU.filter(i => i.cat === cat).forEach(item => {
      grid.appendChild(makeCard(item));
    });
  });
}

function makeCard(item) {
  const c = document.createElement("div");
  c.className = "mcard" + (cart[item.id] ? " in-cart" : "");
  c.id = "mc-" + item.id;
  c.innerHTML = `
    <span class="mpill ${CAT_PILL[item.cat]}">${item.cat}</span>
    <div class="mname">${item.name}</div>
    <div class="mprice">Rs ${item.price}</div>
    ${cart[item.id] ? `<div class="mcard-qty">${cart[item.id]}</div>` : ""}
  `;
  c.addEventListener("click", () => addItem(item));
  return c;
}

function patchCard(item) {
  const old = document.getElementById("mc-" + item.id);
  if (!old) return;
  const fresh = makeCard(item);
  old.replaceWith(fresh);
}

/* ═══════════════════════════════════════════════════════════
   CART LOGIC
═══════════════════════════════════════════════════════════ */
function addItem(item) {
  cart[item.id] = (cart[item.id] || 0) + 1;
  patchCard(item);
  syncBadge();
  refreshBill();
  showToast("Added: " + item.name);
}

function setQty(id, delta) {
  cart[id] = (cart[id] || 0) + delta;
  if (cart[id] <= 0) delete cart[id];
  const item = MENU.find(m => m.id === id);
  patchCard(item);
  syncBadge();
  renderCart();
  refreshBill();
}

document.getElementById("clear-btn").addEventListener("click", () => {
  Object.keys(cart).forEach(id => {
    delete cart[id];
    patchCard(MENU.find(m => m.id == id));
  });
  cart = {};
  syncBadge();
  renderCart();
  refreshBill();
});

function syncBadge() {
  const n = Object.values(cart).reduce((a, b) => a + b, 0);
  const b = document.getElementById("cart-badge");
  b.textContent = n;
  b.classList.toggle("hidden", n === 0);
}

/* ── Build cart items list ────────────────────────────── */
function renderCart() {
  const list = document.getElementById("cart-list");
  const keys = Object.keys(cart).filter(k => cart[k] > 0);

  if (!keys.length) {
    list.innerHTML = `
      <div class="empty-cart">
        <span class="empty-icon">&#128722;</span>
        No items yet.<br>Head to the Menu tab to start an order.
      </div>`;
    return;
  }

  list.innerHTML = keys.map(id => {
    const item = MENU.find(m => m.id == id);
    const qty  = cart[id];
    return `
      <div class="orow">
        <div>
          <div class="o-name">${item.name}</div>
          <div class="o-unit">Rs ${item.price} each</div>
        </div>
        <div class="qty-ctl">
          <button class="qbtn" data-id="${id}" data-delta="-1">&#8722;</button>
          <span class="qnum">${qty}</span>
          <button class="qbtn" data-id="${id}" data-delta="1">&#43;</button>
        </div>
        <div class="o-total">Rs ${item.price * qty}</div>
      </div>`;
  }).join("");

  /* Wire qty buttons */
  list.querySelectorAll(".qbtn").forEach(btn => {
    btn.addEventListener("click", () =>
      setQty(Number(btn.dataset.id), Number(btn.dataset.delta))
    );
  });
}

/* ── Refresh bill totals via C++ backend ──────────────── */
async function refreshBill() {
  const keys = Object.keys(cart).filter(k => cart[k] > 0);

  if (!keys.length) {
    document.getElementById("b-items").textContent  = "0";
    document.getElementById("b-sub").textContent    = "Rs 0";
    document.getElementById("b-tax").textContent    = "Rs 0";
    document.getElementById("b-grand").textContent  = "Rs 0";
    setCalcStatus("", "");
    return;
  }

  const cartItems = keys.map(id => {
    const item = MENU.find(m => m.id == id);
    return { id: item.id, qty: cart[id], price: item.price };
  });

  let result;
  if (backendOK) {
    try {
      result = await apiCalculate(cartItems);
      setCalcStatus("&#10003; Calculated by C++ server", "ok");
    } catch (e) {
      result = fallbackCalculate(cartItems);
      setCalcStatus("&#9888; Backend error — using JS fallback", "err");
    }
  } else {
    result = fallbackCalculate(cartItems);
    setCalcStatus("&#9888; Backend offline — using JS fallback", "err");
  }

  document.getElementById("b-items").textContent  = result.itemCount;
  document.getElementById("b-sub").textContent    = "Rs " + result.subtotal;
  document.getElementById("b-tax").textContent    = "Rs " + result.tax;
  document.getElementById("b-grand").textContent  = "Rs " + result.grandTotal;
}

function setCalcStatus(msg, cls) {
  const el = document.getElementById("calc-status");
  el.innerHTML   = msg;
  el.className   = "calc-status " + cls;
}

/* ═══════════════════════════════════════════════════════════
   PLACE ORDER
═══════════════════════════════════════════════════════════ */
document.getElementById("place-btn").addEventListener("click", placeOrder);

async function placeOrder() {
  const keys = Object.keys(cart).filter(k => cart[k] > 0);
  if (!keys.length) { showToast("Cart is empty!"); return; }

  const customer  = document.getElementById("cust-in").value.trim() || "Walk-in Customer";
   if (currentUser && currentUser.type === 'student') {
    showToast('🎓 Student discount applied! (5% off)');
  }
  const cartItems = keys.map(id => {
    const item = MENU.find(m => m.id == id);
    return { id: item.id, name: item.name, qty: cart[id], price: item.price };
  });

  const btn = document.getElementById("place-btn");
  btn.disabled = true;
  btn.textContent = "PROCESSING…";

  let order;
  if (backendOK) {
    try {
      order = await apiPlaceOrder(customer, cartItems);
      setCalcStatus("&#10003; Order processed by C++ server", "ok");
    } catch (e) {
      order = buildLocalOrder(customer, cartItems);
      setCalcStatus("&#9888; Backend error — local fallback used", "err");
    }
  } else {
    order = buildLocalOrder(customer, cartItems);
  }

  orders.push(order);
  openReceipt(order);
  
orderTracking[order.orderId] = { placed: true, preparing: true, ready: false };
  setTimeout(() => {
      if (orderTracking[order.orderId]) {
          orderTracking[order.orderId].preparing = false;
          orderTracking[order.orderId].ready = true;
          showToast(`Order #${order.orderId} is ready for pickup!`);
      }
  }, 30000);
  /* clear cart */
  Object.keys(cart).forEach(id => {
    delete cart[id];
    patchCard(MENU.find(m => m.id == id));
  });
  cart = {};
  syncBadge();
  renderCart();
  document.getElementById("cust-in").value = "";

  btn.disabled    = false;
  btn.textContent = "PLACE ORDER";
}

/** Local order builder when backend is offline */
function buildLocalOrder(customer, cartItems) {
  const sub   = cartItems.reduce((s, i) => s + i.price * i.qty, 0);
  const tax   = Math.round(sub * 0.05);
  const grand = sub + tax;
  const now   = new Date();
  return {
    orderId:    orders.length + 1,
    customer,
    items:      cartItems.map(i => ({ ...i, rowTotal: i.price * i.qty })),
    subtotal:   sub,
    tax,
    grandTotal: grand,
    time:       now.toLocaleTimeString("en-PK", { hour: "2-digit", minute: "2-digit" }),
  };
}

/* ═══════════════════════════════════════════════════════════
   RECEIPT MODAL
═══════════════════════════════════════════════════════════ */
function openReceipt(o) {
  let h = `
    <div class="rec-meta">
      <div>Order # <strong>${String(o.orderId).padStart(4, "0")}</strong></div>
      <div>Customer: <strong>${o.customer}</strong></div>
      <div>Time: <strong>${o.time}</strong></div>
    </div>
    <hr class="rec-sep"/>`;

  o.items.forEach(i => {
    h += `<div class="rec-row">
      <span>${i.name} &times;${i.qty}</span>
      <span>Rs ${i.rowTotal || i.price * i.qty}</span>
    </div>`;
  });

  h += `
    <hr class="rec-sep"/>
    <div class="rec-row"><span>Subtotal</span><span>Rs ${o.subtotal}</span></div>
    <div class="rec-row"><span>Tax (5%)</span><span>Rs ${o.tax}</span></div>
    <hr class="rec-sep"/>
    <div class="rec-total"><span>TOTAL</span><span>Rs ${o.grandTotal}</span></div>
    <div class="rec-thanks">Thank you! Have a great day &#9786;</div>`;

  document.getElementById("modal-body").innerHTML = h;
  document.getElementById("overlay").classList.remove("hidden");
}

document.getElementById("close-modal-btn").addEventListener("click", () =>
  document.getElementById("overlay").classList.add("hidden")
);

document.getElementById("new-order-btn").addEventListener("click", () => {
  document.getElementById("overlay").classList.add("hidden");
  goPanel("menu");
});

/* ═══════════════════════════════════════════════════════════
   DAILY SUMMARY
═══════════════════════════════════════════════════════════ */
async function renderSummary() {
  document.getElementById("sum-date").textContent =
    new Date().toLocaleDateString("en-PK", {
      weekday: "long", day: "numeric", month: "long", year: "numeric",
    });

  const root = document.getElementById("sum-root");

  /* Try to get authoritative data from C++ backend */
  let data;
  if (backendOK) {
    try {
      data = await apiSummary();
    } catch {
      data = buildLocalSummary();
    }
  } else {
    data = buildLocalSummary();
  }

  if (!data.totalOrders) {
    root.innerHTML = `<div class="empty-sum">No orders today yet.<br>Place some orders to see analytics.</div>`;
    return;
  }

  const { totalOrders, totalRevenue, totalItems, avgBill, topItems, orders: log } = data;
  const maxQ = topItems.length ? topItems[0].qty : 1;

  let h = `
    <div class="stats-grid">
      <div class="stat-card">
        <div class="stat-lbl">Total Orders</div>
        <div class="stat-val">${totalOrders}</div>
      </div>
      <div class="stat-card c-green">
        <div class="stat-lbl">Revenue</div>
        <div class="stat-val">Rs ${totalRevenue}</div>
      </div>
      <div class="stat-card c-blue">
        <div class="stat-lbl">Items Sold</div>
        <div class="stat-val">${totalItems}</div>
      </div>
      <div class="stat-card c-amber">
        <div class="stat-lbl">Avg Bill</div>
        <div class="stat-val">Rs ${avgBill}</div>
      </div>
    </div>
    <div class="sum-cols">
      <div class="sum-box">
        <div class="sum-box-head">Top Selling Items</div>
        <div class="sum-box-body">`;

  topItems.forEach((item, i) => {
    const pct = Math.round((item.qty / maxQ) * 100);
    h += `
      <div class="top-row">
        <span class="t-rank">${i + 1}</span>
        <span class="t-name" title="${item.name}">${item.name}</span>
        <div class="bar-track"><div class="bar-fill" style="width:${pct}%"></div></div>
        <span class="t-qty">${item.qty}</span>
      </div>`;
  });

  h += `</div></div>
      <div class="sum-box">
        <div class="sum-box-head">Orders Log</div>
        <div class="log-list">`;

  [...log].reverse().forEach(o => {
    const desc = o.items.map(i => `${i.name} &times;${i.qty}`).join(", ");
    h += `
      <div class="log-item">
        <div class="log-head">
          <span class="log-name">${o.customer}</span>
          <span class="log-time">${o.time}</span>
        </div>
        <div class="log-foot">
          <div class="log-items">${desc}</div>
          <div class="log-amt">Rs ${o.grandTotal}</div>
        </div>
      </div>`;
  });

  h += `</div></div></div>`;
  root.innerHTML = h;
}

/** Build summary from local orders array when backend is offline */
function buildLocalSummary() {
  if (!orders.length) return { totalOrders: 0 };

  const totalRevenue = orders.reduce((s, o) => s + o.grandTotal, 0);
  const totalItems   = orders.reduce((s, o) => s + o.items.reduce((a, i) => a + i.qty, 0), 0);
  const avgBill      = Math.round(totalRevenue / orders.length);

  const freq = {};
  orders.forEach(o => o.items.forEach(i => { freq[i.name] = (freq[i.name] || 0) + i.qty; }));
  const topItems = Object.entries(freq)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([name, qty]) => ({ name, qty }));

  return {
    totalOrders: orders.length,
    totalRevenue,
    totalItems,
    avgBill,
    topItems,
    orders,
  };
}

/* ═══════════════════════════════════════════════════════════
   TOAST
═══════════════════════════════════════════════════════════ */
let _toastTimer;
function showToast(msg) {
  const el  = document.getElementById("toast");
  const txt = document.getElementById("toast-msg");
  txt.textContent = msg;
  el.classList.add("on");
  clearTimeout(_toastTimer);
  _toastTimer = setTimeout(() => el.classList.remove("on"), 2200);
}

