// 1. Dark/Light Mode
function initThemeToggle() {
    const toggle = document.getElementById('themeToggleBtn');
    const savedTheme = localStorage.getItem('cafe_theme');
    if (savedTheme === 'light') {
        document.body.classList.add('light-mode');
        toggle.innerHTML = '<i class="fas fa-sun"></i>';
    }
    toggle.addEventListener('click', () => {
        document.body.classList.toggle('light-mode');
        const isLight = document.body.classList.contains('light-mode');
        localStorage.setItem('cafe_theme', isLight ? 'light' : 'dark');
        toggle.innerHTML = isLight ? '<i class="fas fa-sun"></i>' : '<i class="fas fa-moon"></i>';
        showToast(isLight ? 'Light mode' : 'Dark mode');
    });
}

// 2. Profile Sidebar
function initSidebar() {
    const sidebar = document.getElementById('profileSidebar');
    const overlay = document.getElementById('sidebarOverlay');
    
    document.getElementById('profileNavBtn').onclick = () => {
        sidebar.classList.add('open');
        overlay.classList.add('active');
    };
    
    document.getElementById('closeSidebarBtn').onclick = () => {
        sidebar.classList.remove('open');
        overlay.classList.remove('active');
    };
    
    overlay.onclick = () => {
        sidebar.classList.remove('open');
        overlay.classList.remove('active');
    };
    
    document.getElementById('feedbackSidebarBtn').onclick = () => {
        document.getElementById('feedbackModal').classList.add('active');
        sidebar.classList.remove('open');
        overlay.classList.remove('active');
    };
}

// 3. Search Menu
function initMenuSearch() {
    const searchInput = document.createElement('input');
    searchInput.type = 'text';
    searchInput.placeholder = '🔍 Search menu...';
    searchInput.className = 'menu-search';
    searchInput.id = 'menuSearchInput';
    
    const secHead = document.querySelector('#panel-menu .sec-head');
    secHead.appendChild(searchInput);
    
    searchInput.addEventListener('input', (e) => {
        const term = e.target.value.toLowerCase();
        document.querySelectorAll('.mcard').forEach(card => {
            const name = card.querySelector('.mname')?.textContent.toLowerCase() || '';
            card.style.display = name.includes(term) ? 'flex' : 'none';
        });
    });
}

